// Choice-owned follow-ups, finite authored stories; not generative text.
const family=s=>s.home==='family'&&!s.story.lost;
const street=s=>s.home==='street'&&!s.story.lost;
const shelter=s=>s.home==='shelter'&&!s.story.lost;
function scene(id,cat,min,ok,text,choices,max){return {id,cat,min,max,ok,text,options:choices.map(([key,label,result,memory,later,effects])=>({id:key,text:label,result,memory,effects:effects||{},after:{days:14,text:later}}))};}
